const SKY = '#1a1a2e';
const GROUND = '#16213e';
const ACCENT = '#0f3460';
const SHADOW = '#0a1929';
const HIGHLIGHT = '#2d6ab4';

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral
function drawSpiral(x, y, r, angle, depth) {
    if (depth === 0) return;

    // Draw arc segment
    ctx.fillStyle = ACCENT;
    ctx.beginPath();
    ctx.arc(x, y, r, angle, angle + Math.PI/4);
    ctx.lineTo(x + r * Math.cos(angle + Math.PI/4), y + r * Math.sin(angle + Math.PI/4));
    ctx.closePath();
    ctx.fill();

    // Recursive calls for next segment
    const nextR = r * 1.1;
    const nextAngle = angle + Math.PI/4;
    drawSpiral(
        x + r * Math.cos(angle),
        y + r * Math.sin(angle),
        nextR,
        nextAngle,
        depth - 1
    );
}

